primary<-g[model=='primary'];chosen<-rbind(head(primary[padj<.1 & NES>0][order(-NES)],2),head(primary[padj<.1 & NES<0][order(NES)],2));if(!nrow(chosen))chosen<-primary[pathway==focus[1]];w(chosen,'01_Endothelial_Hallmark_GSEA/displayed_curves.tsv')
